/**
 * Refreshes src/server/auth/disposable-domains.ts from the
 * disposable-email-domains/disposable-email-domains blocklist (CC0), pinned to
 * one commit so the list changes only when someone runs this and reviews the
 * diff.
 *
 *   npm run update:disposable-domains -- <commit-sha>
 *
 * With no sha it uses the commit already recorded in the generated file. The
 * list is validated (lowercase hostnames, no school or big-provider domain)
 * before anything is written.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { SCHOOLS } from "../../src/config/site";

const OUT = resolve(import.meta.dirname, "../../src/server/auth/disposable-domains.ts");
const REPO = "disposable-email-domains/disposable-email-domains";
const HOST = /^(?=.{1,253}$)([a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z][a-z0-9-]{0,62}$/;
/** Never on the list, whatever upstream says: refusing these would lock real people out. */
const NEVER = ["gmail.com", "outlook.com", "hotmail.com", "yahoo.com", "icloud.com", "proton.me", "protonmail.com", ...SCHOOLS.flatMap((s) => s.domains)];

function recordedSha(): string | undefined {
  try {
    return readFileSync(OUT, "utf8").match(/DISPOSABLE_DOMAINS_SOURCE_COMMIT = "([0-9a-f]{40})"/)?.[1];
  } catch {
    return undefined;
  }
}

async function main() {
  const sha = process.argv[2] ?? recordedSha();
  if (!sha || !/^[0-9a-f]{40}$/.test(sha)) throw new Error("Pass the full 40-character commit sha to pin.");
  const url = `https://raw.githubusercontent.com/${REPO}/${sha}/disposable_email_blocklist.conf`;
  const res = await fetch(url);
  if (!res.ok) throw new Error(`Fetching the list failed: HTTP ${res.status}`);
  const lines = (await res.text()).split("\n").map((l) => l.trim().toLowerCase()).filter((l) => l && !l.startsWith("#"));
  const bad = lines.filter((d) => !HOST.test(d));
  if (bad.length) throw new Error(`Not hostnames: ${bad.slice(0, 5).join(", ")}`);
  const blocked = NEVER.filter((d) => lines.includes(d));
  if (blocked.length) throw new Error(`Upstream lists domains we must accept: ${blocked.join(", ")}`);
  const domains = [...new Set(lines)].sort();
  if (domains.length < 1000) throw new Error(`Only ${domains.length} domains; refusing to write a list this short.`);

  const body = [
    "// Generated by scripts/admin/update-disposable-domains.ts. Do not edit by hand.",
    `// Source: https://github.com/${REPO} (CC0), disposable_email_blocklist.conf at the commit below.`,
    "// Server-only: never import this from src/lib or a client component (it would ship to the browser).",
    "",
    `export const DISPOSABLE_DOMAINS_SOURCE_COMMIT = "${sha}";`,
    "",
    "export const DISPOSABLE_DOMAINS: ReadonlySet<string> = new Set([",
    ...domains.map((d) => `  "${d}",`),
    "]);",
    "",
  ].join("\n");
  writeFileSync(OUT, body);
  console.log(`Wrote ${domains.length} domains from ${sha.slice(0, 7)} to src/server/auth/disposable-domains.ts`);
}

main().catch((e) => {
  console.error(e instanceof Error ? e.message : e);
  process.exit(1);
});
